window.FILE_CONTENTS={"swift/LoopflowMac/Views/TaskFilesView.swift": "#if os(macOS)\nimport AppKit\nimport Loopflow\nimport SwiftUI\nimport WebKit\n\n/// Compact document controls leave room for the file itself.\nenum TaskFileChrome {\n    static let headerHeight: CGFloat = 30\n}\n\nstruct TaskFilesView: View {\n    @Bindable var store: TaskFilesStore\n    let prURL: URL?\n    /// The recorded base moves with a store commit, not a file.\n    let checkoutBase: String?\n    var task: RoadmapTask? = nil\n    var isFocused = true\n    @Environment(\\.palette) private var palette\n    @FocusState private var navigatorFocused: Bool\n\n    private var diffIdentity: String {\n        \"\\(store.selection ?? \"\")|\\(store.changes?.baseCommit ?? \"\")|\\(store.selectedDocument?.editVersion ?? 0)|\\(store.mode)\"\n    }\n\n    var body: some View {\n        VStack(spacing: 0) {\n            HStack(spacing: 4) {\n                ScrollView(.horizontal) {\n                    HStack(spacing: 12) {\n                        if task != nil { Button(\"Brief\") { store.page = .task; store.noteInteraction() } }\n                        Button(\"Changes\") {\n                            store.page = .files; store.mode = .diff; store.navigator = .pinned; store.noteInteraction()\n                        }\n                        if prURL != nil { Button(\"Pull request\") { store.page = .pullRequest; store.noteInteraction() } }\n                        ForEach(store.tabs) { tab in\n                            HStack(spacing: 4) {\n                                Button(tab.path) { store.selectFile(tab.path, mode: .read) }\n                                    .fontWeight(store.page == .files && store.selection == tab.path ? .semibold : .regular)\n                                Button { store.closeTab(tab.id); store.noteInteraction() } label: { Image(systemName: \"xmark\") }\n                                    .accessibilityLabel(\"Close \\(tab.path)\")\n                            }\n                        }\n                    }.buttonStyle(.plain).font(.caption).padding(8)\n                }\n                navigationBar\n            }\n            Divider()\n            if let task, store.page == .task {\n                ScrollView {\n                    VStack(alignment: .leading, spacing: 12) {\n                        Text(task.task.identifier).font(Typography.caption(11)).foregroundStyle(palette.textSecondary)\n                        Text(task.task.name).font(Typography.strong(16))\n                        TaskDueDateView(task: task)\n                        MarkdownBlocks(source: task.task.description).equatable()\n                    }\n                    .frame(maxWidth: .infinity, alignment: .leading)\n                    .padding(14).textSelection(.enabled)\n                }\n                .accessibilityIdentifier(\"browser-task-overview\")\n            } else if task != nil, store.page == .pullRequest {\n                TaskPullRequestView(store: store.pullRequest, url: prURL)\n            } else {\n                VStack(spacing: 0) {\n                    GeometryReader { geometry in\n                        let docked = store.navigator == .pinned && geometry.size.width >= 360\n                        HSplitView {\n                            if docked {\n                                navigator.frame(minWidth: 140, idealWidth: 220, maxWidth: 300)\n                            }\n                            documentPane\n                        }\n                        .overlay(alignment: .topLeading) {\n                            if store.navigator != .closed && !docked {\n                                ZStack(alignment: .topLeading) {\n                                    Color.black.opacity(0.001).contentShape(Rectangle())\n                                        .onTapGesture { dismissNavigator() }\n                                    navigator\n                                        .frame(width: min(360, geometry.size.width),\n                                               height: max(0, geometry.size.height - 8))\n                                        .clipShape(RoundedRectangle(cornerRadius: 10))\n                                        .overlay(RoundedRectangle(cornerRadius: 10).strokeBorder(palette.border))\n                                        .shadow(color: .black.opacity(0.2), radius: 12, x: 3, y: 6)\n                                        .accessibilityIdentifier(\"files-navigation-dropdown\")\n                                }\n                            }\n                        }\n                    }\n                }\n                .background {\n                    HStack {\n                        Button(\"Choose file\") { toggleNavigator() }\n                            .keyboardShortcut(\"p\", modifiers: .command)\n                        Button(\"Pin file navigation\") { store.togglePinnedNavigator() }\n                            .keyboardShortcut(\"b\", modifiers: [.control, .command])\n                    }.disabled(!isFocused).hidden().accessibilityHidden(true).frame(width: 0, height: 0)\n                }\n            }\n        }\n        .background(palette.background)\n        .tint(palette.actionInk)\n        .task(id: \"\\(store.page)|\\(checkoutBase ?? \"\")\") {\n            guard task == nil || store.page == .files else { return }\n            store.observeFiles()\n            await store.refreshChanges()\n        }\n        .task(id: \"\\(store.selection ?? \"\")|\\(store.mode)\") {\n            if store.mode != .diff { await store.loadFile() }\n        }\n        .task(id: diffIdentity) { if store.mode == .diff { await store.loadDiff() } }\n    }\n\n    private func toggleNavigator() {\n        store.noteInteraction()\n        let wasFiles = store.page == .files\n        store.page = .files\n        if wasFiles || store.navigator == .closed { store.toggleNavigator() }\n        navigatorFocused = store.navigator != .closed\n    }\n\n    private func dismissNavigator() {\n        store.dismissNavigator()\n        navigatorFocused = false\n        if let editor = store.selectedDocument?.editor, editor.window != nil {\n            editor.window?.makeFirstResponder(editor)\n        }\n    }\n\n    private var navigator: some View {\n        VStack(spacing: 0) {\n            HStack {\n                Image(systemName: \"magnifyingglass\").foregroundStyle(palette.textSecondary)\n                TextField(\"Find in scratch and changes\", text: $store.search)\n                    .textFieldStyle(.plain).focused($navigatorFocused)\n                    .accessibilityIdentifier(\"files-search\")\n                    .onSubmit {\n                        let paths = store.scratchPaths + store.changedPaths\n                        if let path = paths.first {\n                            selectFile(path, mode: store.scratchPaths.contains(path) ? .read : .diff)\n                        }\n                    }\n                Button { store.togglePinnedNavigator() } label: {\n                    Image(systemName: store.navigator == .pinned ? \"pin.slash\" : \"pin\")\n                }\n                .buttonStyle(.plain)\n                .accessibilityLabel(store.navigator == .pinned ? \"Close file navigation\" : \"Pin file navigation\")\n                .accessibilityIdentifier(\"files-pin-navigator\")\n            }.padding(10)\n            Divider()\n            ScrollView {\n                LazyVStack(alignment: .leading, spacing: 4) {\n                    sectionHeader(\"scratch\", expanded: $store.showsScratch)\n                    if store.showsScratch {\n                        ForEach(store.scratchPaths, id: \\.self) { path in\n                            row(path, label: String(path.dropFirst(\"scratch/\".count)), mode: .read)\n                        }\n                        if store.changes?.scratchTruncated == true {\n                            Text(\"Scratch list truncated\").font(.caption).foregroundStyle(palette.textSecondary)\n                        }\n                    }\n                    sectionHeader(\"Changed files\", expanded: $store.showsChanges).padding(.top, 12)\n                    if store.showsChanges {\n                        ForEach(store.changedPaths, id: \\.self) { path in row(path, label: path, mode: .diff) }\n                    }\n                    if store.isRefreshingChanges, store.changes == nil { ProgressView().controlSize(.small) }\n                    if let reason = store.changesError {\n                        Text(reason).font(.caption).foregroundStyle(palette.warning)\n                    } else if store.changes != nil, store.scratchPaths.isEmpty, store.changedPaths.isEmpty {\n                        Text(store.search.isEmpty ? \"No scratch or changed files\" : \"No matching files\")\n                            .font(.caption).foregroundStyle(palette.textSecondary)\n                    }\n                }.padding(10)\n            }\n            if let sha = store.changes?.baseCommit {\n                Text(\"Parent \u00b7 \\(sha.prefix(10))\").font(.system(size: 10, design: .monospaced))\n                    .foregroundStyle(palette.textSecondary).padding(8)\n            }\n            if store.query.remoteMachine == nil, let directory = store.changes?.recoveryDirectory {\n                Button(\"Open saved versions \u2197\") {\n                    NSWorkspace.shared.open(URL(fileURLWithPath: directory))\n                }.buttonStyle(WorkPlainButtonStyle()).font(.caption).lineLimit(1).padding(8)\n            }\n        }\n        .background(palette.surfaceMuted)\n        .onAppear { if store.navigator == .dropdown { navigatorFocused = true } }\n        .onExitCommand { dismissNavigator() }\n    }\n\n    private var navigationBar: some View {\n        HStack(spacing: 8) {\n            Button { toggleNavigator() } label: {\n                Image(systemName: \"sidebar.left\")\n                    .frame(width: 24, height: 28).contentShape(Rectangle())\n            }\n            .buttonStyle(.plain)\n            .help(\"Show or hide file browser (\u2318P)\")\n            .accessibilityLabel(\"Show or hide file browser\")\n            .accessibilityIdentifier(\"files-toggle-navigator\")\n            if store.page == .files, let document = store.selectedDocument, document.snapshot?.state == .text {\n                Button {\n                    Task {\n                        await document.save(issue: store.issue, query: store.query)\n                        await store.refresh()\n                    }\n                } label: {\n                    Image(systemName: document.saving ? \"arrow.triangle.2.circlepath\" : \"square.and.arrow.down\")\n                }\n                .buttonStyle(.plain)\n                .help(document.saving ? \"Saving\u2026\" : \"Save\")\n                .accessibilityLabel(\"Save\")\n                .disabled(!document.canSave)\n                .keyboardShortcut(\"s\", modifiers: .command)\n                .fixedSize()\n            }\n            if store.page == .files {\n                Picker(\"View\", selection: Binding(get: { store.mode }, set: { store.mode = $0; store.noteInteraction() })) {\n                    Text(\"Read\").tag(TaskFilesStore.Mode.read)\n                    Text(\"Edit\").tag(TaskFilesStore.Mode.edit)\n                    Text(\"Diff\").tag(TaskFilesStore.Mode.diff)\n                        .disabled(store.changesError != nil)\n                }.pickerStyle(.menu).labelsHidden()\n                    .accessibilityLabel(\"View\").frame(width: 70).fixedSize()\n            }\n        }\n        .font(Typography.caption(11)).padding(.horizontal, 10)\n        .frame(height: TaskFileChrome.headerHeight)\n        .fixedSize(horizontal: true, vertical: false)\n    }\n\n\n    private var documentPane: some View {\n        VStack(spacing: 0) {\n            if let error = store.error {\n                Text(error).font(.caption).foregroundStyle(palette.warning).padding(8)\n            }\n            if let reason = store.selectedDocument?.readOnlyReason {\n                Text(reason).font(.caption).padding(8)\n            }\n            if let document = store.selectedDocument, let external = document.external {\n                Text(\"\\(stateLabel(external.state)) \u00b7 local draft retained; saving unavailable\")\n                    .font(.caption).padding(8)\n            }\n            content\n            if let document = store.selectedDocument {\n                if let message = document.saveMessage {\n                    Text(message).font(.system(size: 10)).foregroundStyle(palette.textSecondary).padding(6)\n                } else if document.dirty {\n                    Text(store.autosave && document.canSave ? \"Autosave pending \u00b7 draft retained\" : \"Unsaved draft \u00b7 retained in this window\")\n                        .font(.system(size: 10)).foregroundStyle(palette.textSecondary).padding(6)\n                }\n                if !document.recoveries.isEmpty {\n                    HStack {\n                        Text(document.recoveries.contains { $0.changed }\n                             ? \"Recovery needs attention\" : \"Previous versions retained\")\n                        Menu(\"Recovery \u00b7 \\(document.recoveries.count)\") {\n                            ForEach(Array(document.recoveries.enumerated()), id: \\.element.id) { index, recovery in\n                                Button(\"\\(recovery.changed ? \"\u26a0 \" : \"\")Previous version \\(index + 1)\") {\n                                    NSWorkspace.shared.open(URL(fileURLWithPath: recovery.directory))\n                                }.help(recovery.message)\n                            }\n\u2026 (268 more lines)", "swift/LoopflowMac/Views/TaskPullRequestView.swift": "#if os(macOS)\nimport Loopflow\nimport SwiftUI\n\nstruct TaskPullRequestView: View {\n    @Bindable var store: PullRequestStore\n    let url: URL?\n    @Environment(\\.palette) private var palette\n    @State private var showsChecks = false\n\n    var body: some View {\n        ScrollView {\n            VStack(alignment: .leading, spacing: 16) {\n                HStack {\n                    Text(\"Pull request\").font(Typography.strong(14))\n                    Spacer()\n                    if let url {\n                        Button { Task { await refresh(url) } } label: {\n                            Image(systemName: \"arrow.clockwise\")\n                        }.buttonStyle(.plain).disabled(store.refreshing)\n                            .accessibilityLabel(\"Refresh pull request\")\n                        Link(destination: url) { Image(systemName: \"arrow.up.right.square\") }\n                            .accessibilityLabel(\"Open pull request on GitHub\")\n                    }\n                }\n                if let error = store.error {\n                    Text(error).font(.caption).foregroundStyle(palette.warning)\n                    if store.pullRequest != nil { Text(\"Showing the last successful reading\").font(.caption) }\n                }\n                if let pr = store.pullRequest {\n                    overview(pr)\n                    Divider()\n                    checks(pr)\n                    Divider()\n                    reviewers(pr)\n                    Divider()\n                    VStack(alignment: .leading, spacing: 8) {\n                        Text(\"Description\").font(Typography.strong(13))\n                        if pr.body.isEmpty { Text(\"No description\").foregroundStyle(palette.textSecondary) }\n                        else { MarkdownBlocks(source: pr.body).equatable() }\n                    }\n                    Divider()\n                    fileList(pr)\n                    if let updated = store.updatedAt {\n                        Text(\"Updated \\(updated, style: .relative) ago\")\n                            .font(.caption2).foregroundStyle(palette.textSecondary)\n                    }\n                } else if store.refreshing {\n                    ProgressView(\"Reading GitHub\u2026\").frame(maxWidth: .infinity)\n                } else if url == nil {\n                    Text(\"No pull request published yet.\").foregroundStyle(palette.textSecondary)\n                }\n            }\n            .font(Typography.body(12))\n            .padding(14)\n            .frame(maxWidth: .infinity, alignment: .leading)\n            .textSelection(.enabled)\n        }\n        .background(palette.background)\n        .accessibilityIdentifier(\"browser-pull-request\")\n        .task(id: url) { await store.refresh(url) }\n        .task(id: \"\\(store.showsFiles)|\\(store.updatedAt?.timeIntervalSince1970 ?? 0)\") {\n            if store.showsFiles { await store.loadFiles() }\n        }\n    }\n\n    private func refresh(_ url: URL) async {\n        await store.refresh(url)\n    }\n\n    private func overview(_ pr: GitHubPullRequest) -> some View {\n        VStack(alignment: .leading, spacing: 8) {\n            HStack {\n                Text(pr.statusLabel).font(Typography.strong(11))\n                    .padding(.horizontal, 8).padding(.vertical, 4)\n                    .background(palette.surfaceMuted, in: Capsule())\n                Text(\"#\\(pr.number)\").foregroundStyle(palette.textSecondary)\n                Spacer()\n            }\n            Text(pr.title).font(Typography.strong(18)).fixedSize(horizontal: false, vertical: true)\n            Text(\"\\(pr.headRefName) \u2192 \\(pr.baseRefName)\")\n                .font(Typography.code(10)).foregroundStyle(palette.textSecondary)\n                .lineLimit(2).truncationMode(.middle)\n            HStack(spacing: 10) {\n                Text(\"\\(pr.changedFiles) files\")\n                Text(\"+\\(pr.additions)\").foregroundStyle(.green)\n                Text(\"\u2212\\(pr.deletions)\").foregroundStyle(.red)\n            }.font(Typography.code(12))\n        }\n    }\n\n    private func checks(_ pr: GitHubPullRequest) -> some View {\n        VStack(alignment: .leading, spacing: 8) {\n            Text(\"Checks\").font(Typography.strong(13))\n            if let checks = pr.statusCheckRollup {\n                if checks.isEmpty { Text(\"No checks reported\").foregroundStyle(palette.textSecondary) }\n                if !checks.isEmpty {\n                    DisclosureGroup(isExpanded: $showsChecks) {\n                        ForEach(Array(checks.enumerated()), id: \\.offset) { _, check in\n                            HStack(alignment: .top, spacing: 8) {\n                                Image(systemName: check.failed ? \"xmark.circle\" : check.passed ? \"checkmark.circle\" : \"clock\")\n                                    .foregroundStyle(check.failed ? Color.red : check.passed ? Color.green : palette.textSecondary)\n                                VStack(alignment: .leading, spacing: 2) {\n                                    if let link = check.link { Link(check.label, destination: link) }\n                                    else { Text(check.label) }\n                                    Text(check.result.replacingOccurrences(of: \"_\", with: \" \").capitalized)\n                                        .font(.caption2).foregroundStyle(palette.textSecondary)\n                                }\n                                Spacer(minLength: 0)\n                            }\n                        }\n                    } label: {\n                        Text(pr.checksSummary)\n                            .font(.caption)\n                    }\n                }\n            } else { Text(\"Check status unavailable\").foregroundStyle(palette.textSecondary) }\n        }\n    }\n\n    private func reviewers(_ pr: GitHubPullRequest) -> some View {\n        VStack(alignment: .leading, spacing: 8) {\n            Text(\"Review\").font(Typography.strong(13))\n            Text(pr.reviewLabel)\n            if pr.reviewRequests.isEmpty {\n                Text(\"No pending review requests\").foregroundStyle(palette.textSecondary)\n            } else {\n                Text(\"Waiting on reviewers\").font(Typography.strong(11))\n                ForEach(Array(pr.reviewRequests.enumerated()), id: \\.offset) { _, reviewer in\n                    Label(reviewer.label, systemImage: \"person.crop.circle\")\n                }\n            }\n        }\n    }\n\n    private func coloredPatch(_ patch: String) -> AttributedString {\n        var result = AttributedString()\n        for line in patch.split(separator: \"\\n\", omittingEmptySubsequences: false) {\n            var text = AttributedString(String(line) + \"\\n\")\n            if line.hasPrefix(\"+\") { text.foregroundColor = .green }\n            else if line.hasPrefix(\"-\") { text.foregroundColor = .red }\n            else if line.hasPrefix(\"@@\") { text.foregroundColor = palette.textSecondary }\n            result.append(text)\n        }\n        return result\n    }\n\n    private func fileList(_ pr: GitHubPullRequest) -> some View {\n        DisclosureGroup(isExpanded: $store.showsFiles) {\n            VStack(alignment: .leading, spacing: 10) {\n                if let error = store.filesError {\n                    Text(error).font(.caption).foregroundStyle(palette.warning)\n                    Button(\"Retry diffs\") { Task { await refresh(pr.url) } }\n                }\n                if store.loadingFiles { ProgressView().controlSize(.small) }\n                if let files = store.files {\n                    ForEach(files) { file in\n                        DisclosureGroup(isExpanded: Binding(\n                            get: { store.expandedFiles.contains(file.id) },\n                            set: { if $0 { store.expandedFiles.insert(file.id) } else { store.expandedFiles.remove(file.id) } }\n                        )) {\n                            VStack(alignment: .leading, spacing: 6) {\n                                if let previous = file.previousFilename {\n                                    Text(\"Renamed from \\(previous)\").font(.caption)\n                                }\n                                if let patch = file.patch, store.expandedFiles.contains(file.id) {\n                                    ScrollView(.horizontal) {\n                                        Text(coloredPatch(patch)).font(Typography.code(10)).fixedSize(horizontal: true, vertical: false)\n                                            .padding(8)\n                                    }.background(palette.surfaceMuted, in: RoundedRectangle(cornerRadius: 6))\n                                }\n                                if file.incompletePatch {\n                                    Text(\"GitHub omitted some or all of this patch (large or binary file).\")\n                                        .font(.caption).foregroundStyle(palette.textSecondary)\n                                }\n                                if let link = file.blobURL { Link(\"Open file on GitHub \u2197\", destination: link).font(.caption) }\n                            }\n                        } label: {\n                            VStack(alignment: .leading, spacing: 3) {\n                                Text(file.filename).font(Typography.code(11)).lineLimit(2).truncationMode(.middle)\n                                HStack(spacing: 6) {\n                                    Text(file.status.capitalized).foregroundStyle(palette.textSecondary)\n                                    Text(\"+\\(file.additions)\").foregroundStyle(.green)\n                                    Text(\"\u2212\\(file.deletions)\").foregroundStyle(.red)\n                                }.font(.caption2)\n                            }\n                        }\n                    }\n                    if files.count < pr.changedFiles {\n                        Text(\"Showing \\(files.count) of \\(pr.changedFiles) files returned by GitHub.\")\n                            .font(.caption).foregroundStyle(palette.textSecondary)\n                    }\n                }\n            }.padding(.top, 8)\n        } label: { Text(\"Files changed \u00b7 \\(pr.changedFiles)\").font(Typography.strong(13)) }\n    }\n}\n#endif\n", "swift/LoopflowMac/PullRequestStore.swift": "#if os(macOS)\nimport Foundation\nimport Observation\n\n/// GitHub's published PR, independent of local uncommitted changes.\nstruct GitHubPullRequest: Decodable, Sendable {\n    let number: Int\n    let url: URL\n    let title: String\n    let body: String\n    let state: String\n    let isDraft: Bool\n    let additions: Int\n    let deletions: Int\n    let changedFiles: Int\n    let headRefOid: String\n    let baseRefOid: String\n    let headRefName: String\n    let baseRefName: String\n    let reviewDecision: String\n    let reviewRequests: [Reviewer]\n    let statusCheckRollup: [Check]?\n\n    struct Reviewer: Decodable, Sendable {\n        let login: String?\n        let name: String?\n        let slug: String?\n        var label: String { login ?? slug ?? name ?? \"Unknown reviewer\" }\n    }\n\n    struct Check: Decodable, Sendable {\n        let name: String?\n        let context: String?\n        let status: String?\n        let conclusion: String?\n        let state: String?\n        let detailsUrl: URL?\n        let targetUrl: URL?\n\n        var label: String { name ?? context ?? \"Check\" }\n        var result: String {\n            if let conclusion, !conclusion.isEmpty { return conclusion }\n            return state ?? status ?? \"UNKNOWN\"\n        }\n        var link: URL? { detailsUrl ?? targetUrl }\n        var passed: Bool { result == \"SUCCESS\" }\n        var skipped: Bool { [\"NEUTRAL\", \"SKIPPED\"].contains(result) }\n        var pending: Bool { [\"QUEUED\", \"IN_PROGRESS\", \"PENDING\", \"WAITING\", \"REQUESTED\"].contains(result) }\n        var failed: Bool { [\"FAILURE\", \"ERROR\", \"CANCELLED\", \"TIMED_OUT\", \"ACTION_REQUIRED\", \"STARTUP_FAILURE\"].contains(result) }\n    }\n\n    var checksSummary: String {\n        guard let checks = statusCheckRollup else { return \"Check status unavailable\" }\n        if checks.isEmpty { return \"No checks reported\" }\n        let groups = [\n            (checks.filter(\\.passed).count, \"passed\"),\n            (checks.filter(\\.failed).count, \"failed\"),\n            (checks.filter(\\.pending).count, \"pending\"),\n            (checks.filter(\\.skipped).count, \"skipped\"),\n            (checks.filter { !$0.passed && !$0.failed && !$0.pending && !$0.skipped }.count, \"unknown\")\n        ]\n        return groups.filter { $0.0 > 0 }.map { \"\\($0.0) \\($0.1)\" }.joined(separator: \" \u00b7 \")\n    }\n\n    var statusLabel: String { isDraft && state == \"OPEN\" ? \"Draft\" : state.capitalized }\n    var reviewLabel: String {\n        switch reviewDecision {\n        case \"APPROVED\": \"Approved\"\n        case \"CHANGES_REQUESTED\": \"Changes requested\"\n        case \"REVIEW_REQUIRED\": \"Review required\"\n        default: \"No review decision\"\n        }\n    }\n}\n\nstruct GitHubPullRequestFile: Decodable, Sendable, Identifiable {\n    let filename: String\n    let previousFilename: String?\n    let status: String\n    let additions: Int\n    let deletions: Int\n    let patch: String?\n    let blobURL: URL?\n    var id: String { filename }\n\n    enum CodingKeys: String, CodingKey {\n        case filename, status, additions, deletions, patch\n        case previousFilename = \"previous_filename\"\n        case blobURL = \"blob_url\"\n    }\n\n    var incompletePatch: Bool {\n        guard let patch else { return true }\n        let lines = patch.split(separator: \"\\n\", omittingEmptySubsequences: false)\n        return lines.filter { $0.hasPrefix(\"+\") }.count < additions\n            || lines.filter { $0.hasPrefix(\"-\") }.count < deletions\n    }\n}\n\n@MainActor\n@Observable\nfinal class PullRequestStore {\n    private(set) var pullRequest: GitHubPullRequest?\n    private(set) var files: [GitHubPullRequestFile]?\n    private(set) var error: String?\n    private(set) var filesError: String?\n    private(set) var refreshing = false\n    private(set) var loadingFiles = false\n    private(set) var updatedAt: Date?\n    var showsFiles = false\n    var expandedFiles: Set<String> = []\n    private var requestedURL: URL?\n    private var generation = 0\n    private var fileGeneration = 0\n\n    func refresh(_ url: URL?) async {\n        generation += 1\n        let generation = generation\n        if requestedURL != url || url == nil {\n            pullRequest = nil\n            files = nil\n            error = nil\n            filesError = nil\n            showsFiles = false\n            expandedFiles.removeAll()\n            updatedAt = nil\n        }\n        requestedURL = url\n        fileGeneration += 1\n        loadingFiles = false\n        guard let url else {\n            refreshing = false\n            return\n        }\n        refreshing = true\n        defer { if self.generation == generation { refreshing = false } }\n        do {\n            let text = try await LocalWaveAgentLauncher.queryGitHub([\n                \"pr\", \"view\", url.absoluteString, \"--json\",\n                \"number,url,title,body,state,isDraft,additions,deletions,changedFiles,headRefOid,baseRefOid,headRefName,baseRefName,reviewDecision,reviewRequests,statusCheckRollup\"\n            ])\n            let next = try JSONDecoder().decode(GitHubPullRequest.self, from: Data(text.utf8))\n            guard !Task.isCancelled, generation == self.generation else { return }\n            files = nil\n            filesError = nil\n            pullRequest = next\n            error = nil\n            updatedAt = Date()\n        } catch {\n            guard !Task.isCancelled, generation == self.generation else { return }\n            self.error = error.localizedDescription\n        }\n    }\n\n    func loadFiles() async {\n        guard let pr = pullRequest, files == nil else { return }\n        fileGeneration += 1\n        let generation = fileGeneration\n        loadingFiles = true\n        defer { if fileGeneration == generation { loadingFiles = false } }\n        do {\n            let parts = pr.url.pathComponents.filter { $0 != \"/\" }\n            guard parts.count >= 4, parts[2] == \"pull\", let host = pr.url.host else {\n                throw LocalLfError(errorDescription: \"GitHub PR URL is unavailable.\")\n            }\n            let text = try await LocalWaveAgentLauncher.queryGitHub([\n                \"api\", \"--hostname\", host, \"--paginate\", \"--slurp\",\n                \"repos/\\(parts[0])/\\(parts[1])/pulls/\\(pr.number)/files?per_page=100\"\n            ])\n            let pages = try JSONDecoder().decode([[GitHubPullRequestFile]].self, from: Data(text.utf8))\n            // Files are read from the PR's moving head; do not label another head's patch with this one.\n            let head = try await LocalWaveAgentLauncher.queryGitHub([\n                \"pr\", \"view\", pr.url.absoluteString, \"--json\", \"headRefOid,baseRefOid\", \"--jq\", \"[.headRefOid, .baseRefOid] | join(\\\" \\\")\"\n            ]).trimmingCharacters(in: .whitespacesAndNewlines)\n            guard head == \"\\(pr.headRefOid) \\(pr.baseRefOid)\" else {\n                throw LocalLfError(errorDescription: \"The PR changed while loading diffs. Refresh to read the new head.\")\n            }\n            let next = pages.flatMap { $0 }\n            guard !Task.isCancelled, generation == fileGeneration, pullRequest?.url == pr.url, pullRequest?.headRefOid == pr.headRefOid, pullRequest?.baseRefOid == pr.baseRefOid else { return }\n            files = next\n            filesError = nil\n        } catch {\n            guard !Task.isCancelled, generation == fileGeneration, pullRequest?.url == pr.url, pullRequest?.headRefOid == pr.headRefOid, pullRequest?.baseRefOid == pr.baseRefOid else { return }\n            filesError = error.localizedDescription\n        }\n    }\n}\n#endif\n", "rust/loopflow/src/ops/task/directory.rs": "use std::path::Path;\n\nuse serde::{Deserialize, Serialize};\n\nuse super::{file_context, file_store, task_error, validate_task_relative_path};\nuse crate::ops::error::OpsResult;\n\nconst PAGE_SIZE: usize = 500;\n\n#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]\n#[serde(rename_all = \"snake_case\")]\npub enum TaskFileKind {\n    File,\n    Directory,\n    Symlink,\n}\n\n#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]\npub struct TaskFileEntry {\n    pub path: String,\n    pub kind: TaskFileKind,\n}\n\nimpl TaskFileEntry {\n    fn sort_key(&self) -> (bool, &str) {\n        (self.kind != TaskFileKind::Directory, &self.path)\n    }\n}\n\n#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]\npub struct TaskDirectory {\n    pub path: String,\n    pub entries: Vec<TaskFileEntry>,\n    pub next_cursor: Option<String>,\n}\n\n#[derive(Debug, Serialize, Deserialize)]\nstruct Cursor {\n    directory: String,\n    show_ignored: bool,\n    last: TaskFileEntry,\n}\n\npub fn task_files(\n    issue: &str,\n    directory: &str,\n    cursor: Option<&str>,\n    show_ignored: bool,\n) -> OpsResult<TaskDirectory> {\n    let checkout = file_context(&file_store()?, issue)?;\n    directory_snapshot(&checkout.worktree, directory, cursor, show_ignored)\n}\n\nfn directory_snapshot(\n    worktree: &Path,\n    directory: &str,\n    cursor: Option<&str>,\n    show_ignored: bool,\n) -> OpsResult<TaskDirectory> {\n    let directory = if directory == \".\" || directory.is_empty() {\n        String::new()\n    } else {\n        validate_task_relative_path(directory)?\n    };\n    if Path::new(&directory)\n        .components()\n        .any(|part| part.as_os_str() == \".git\")\n    {\n        return Err(task_error(\"Git metadata is not a Task directory\"));\n    }\n    let cursor: Option<Cursor> = cursor\n        .map(|value| {\n            let bytes = hex::decode(value).map_err(|_| task_error(\"Invalid directory cursor\"))?;\n            serde_json::from_slice(&bytes).map_err(|_| task_error(\"Invalid directory cursor\"))\n        })\n        .transpose()?;\n    if cursor\n        .as_ref()\n        .is_some_and(|cursor| cursor.directory != directory || cursor.show_ignored != show_ignored)\n    {\n        return Err(task_error(\n            \"Directory cursor belongs to another directory or ignored-file selection\",\n        ));\n    }\n    let root = worktree.canonicalize()?;\n    let absolute = root.join(&directory).canonicalize()?;\n    if !absolute.starts_with(&root) || !absolute.is_dir() {\n        return Err(task_error(\"Directory must remain inside the Task worktree\"));\n    }\n    let mut entries = Vec::new();\n    for entry in std::fs::read_dir(&absolute)? {\n        let entry = entry?;\n        if entry.file_name() == \".git\" {\n            continue;\n        }\n        let name = entry\n            .file_name()\n            .into_string()\n            .map_err(|_| task_error(\"Task directory contains a non-UTF-8 filename\"))?;\n        let kind = entry.file_type()?;\n        let kind = if kind.is_symlink() {\n            TaskFileKind::Symlink\n        } else if kind.is_dir() {\n            TaskFileKind::Directory\n        } else if kind.is_file() {\n            TaskFileKind::File\n        } else {\n            continue;\n        };\n        let path = if directory.is_empty() {\n            name\n        } else {\n            format!(\"{directory}/{name}\")\n        };\n        entries.push(TaskFileEntry { path, kind });\n    }\n    if !show_ignored && !entries.is_empty() {\n        let ignored =\n            crate::git::ignored_paths(&root, entries.iter().map(|entry| entry.path.as_str()))\n                .map_err(task_error)?;\n        entries.retain(|entry| !ignored.contains(&entry.path));\n    }\n    entries.sort_by(|left, right| left.sort_key().cmp(&right.sort_key()));\n    if let Some(cursor) = &cursor {\n        entries.retain(|entry| entry.sort_key() > cursor.last.sort_key());\n    }\n    let has_more = entries.len() > PAGE_SIZE;\n    entries.truncate(PAGE_SIZE);\n    let next_cursor = if has_more {\n        Some(hex::encode(\n            serde_json::to_vec(&Cursor {\n                directory: directory.clone(),\n                show_ignored,\n                last: entries.last().expect(\"full page has entries\").clone(),\n            })\n            .map_err(task_error)?,\n        ))\n    } else {\n        None\n    };\n    Ok(TaskDirectory {\n        path: directory,\n        entries,\n        next_cursor,\n    })\n}\n\n#[cfg(test)]\nmod tests {\n    use super::{directory_snapshot, TaskFileKind};\n\n    #[test]\n    fn task_files_pages_include_unchanged_untracked_and_bounded_links() {\n        let repo = loopflow_test_support::TestRepo::new();\n        let worktree = repo.path();\n        std::fs::write(repo.path().join(\".gitignore\"), \"ignored/\\n\").unwrap();\n        for directory in [\"nested\", \"ignored\"] {\n            std::fs::create_dir(repo.path().join(directory)).unwrap();\n        }\n        for index in 0..505 {\n            std::fs::write(repo.path().join(format!(\"file-{index:03}\")), \"\").unwrap();\n        }\n        std::os::unix::fs::symlink(\"nested\", repo.path().join(\"link\")).unwrap();\n        let first = directory_snapshot(worktree, \"\", None, false).unwrap();\n        assert_eq!(first.entries.len(), 500);\n        assert_eq!(first.entries[0].path, \"nested\");\n        assert!(!first\n            .entries\n            .iter()\n            .any(|entry| entry.path == \".git\" || entry.path == \"ignored\"));\n        let second = directory_snapshot(worktree, \"\", first.next_cursor.as_deref(), false).unwrap();\n        assert!(second.next_cursor.is_none());\n        assert!(second\n            .entries\n            .iter()\n            .any(|entry| entry.path == \"link\" && entry.kind == TaskFileKind::Symlink));\n        assert!(first\n            .entries\n            .iter()\n            .all(|entry| !second.entries.contains(entry)));\n        let visible = directory_snapshot(worktree, \"\", None, true).unwrap();\n        assert!(visible.entries.iter().any(|entry| entry.path == \"ignored\"));\n        assert!(\n            directory_snapshot(worktree, \"nested\", first.next_cursor.as_deref(), false).is_err()\n        );\n        assert!(directory_snapshot(worktree, \"\", first.next_cursor.as_deref(), true).is_err());\n        assert!(directory_snapshot(worktree, \".git\", None, true).is_err());\n        let outside = tempfile::tempdir().unwrap();\n        std::os::unix::fs::symlink(outside.path(), repo.path().join(\"outside\")).unwrap();\n        assert!(directory_snapshot(worktree, \"outside\", None, true).is_err());\n    }\n}\n", "swift/README.md": "# Loopflow for macOS\n\n```bash\nuv run python scripts/loopflow-dev.py run          # build and launch\nuv run python scripts/loopflow-dev.py install      # install without launching\nuv run python scripts/loopflow-dev.py run-debug    # launch with logs visible\nuv run python scripts/loopflow-dev.py test         # run Swift tests\n```\n\nThe development app's main-Machine commands forward to the installed CLI.\nSelect a private `LF_HOME` to use this checkout's bundled CLI with separate data.\nFor populated data, use [offline data clones](../docs/data-clones.md):\n`lf clone run` selects the clone's pinned helper, confines Desktop and its embedded\nterminals, preserves source checkouts read-only, and reports copied Sessions'\ncontinuation limits. A bare SQLite copy provides no filesystem, provider or client\nisolation.\nRepository selectors list only Git main checkouts. Linked worktrees stay visible\nonly through the Task Work that owns them.\n\nA returning launch opens on the workspace saved at `<Machine>/desktop-cache/workspace.json`\nand shows **Updating\u2026** until this launch's reads replace it. Saved rows open\nand navigate; Graph process state, Task condition, Session state and every action except\nopening a Session wait for the fresh read. The Portfolio window opens from the\nsame saved workspace. A failed refresh keeps what is shown under one\n**Couldn't update** line. Repeated identical Session errors leave the displayed\nreading unchanged; failed per-Wave or truncated replacements keep previously readable planning,\nincluding its saved copy. A new error or recovery updates it.\nThe bundled helper cannot migrate the installed store: schema changes require a\npublished release installed through `lf install`. Delete the file to start\nfrom **Loading workspace\u2026**.\n\n```sh\nuv run python scripts/benchmarks/desktop-performance/timings.py   # how long your launches took\n```\n\nEach launch records when its first frame, saved workspace and fresh workspace\narrived, and how long each `lf` read took, under `desktop-cache/timings/` in\nthe Machine. Durations and command names only; the files stay on this machine.\n\nWorking Tasks lists every started, uncompleted Task, on any Machine this store\nrecords, in the repository plan's order (waiting first, then rank). It is the\nrepository's built-in query, so opening a Task neither adds nor reorders it.\nClick a Wave to scope the sidebar to its Working Tasks and subwaves; its board's\nBacklog keeps the unstarted ones. **\u2039 Repo** returns to Working Tasks. Unstarted Tasks\nopen their brief beside **Start**, which runs the Task's Workflow; opening alone\nstarts nothing. Waves follow Tasks in the same scrolling sidebar, with counts\nfrom the planning inventory.\n\nClick a row to select its retained workspace. The title-bar **Repo \u203a Wave \u203a Task**\npath follows hierarchy: click a name to go there, or the **\u203a** after it to list and\nsearch what it contains; Back and **\u2318[ / \u2318]** follow visits. **\u2318K** searches Work\nacross repositories and opens another repository in its own window. Its\n**Sidebar shows** picker filters Working tasks / Available / Running without\nchanging the selected Work. Click a Wave and its name moves into the\nsidebar header; the rows below are its Tasks, in plan order, until\n**\u2039 repo** returns to Working Tasks. **\u23181\u20139** selects the sidebar's Task rows by\nposition and **\u2303Tab / \u2303\u21e7Tab** cycles them. Missing slots do nothing. Selecting a\nDashboard's Task, from any of these, keeps the Dashboard in the path, as its tile does.\nWith sidebar focus, **\u2318F** searches its visible Tasks and Waves; **Search all Work**\nwidens the same navigator. **Shift-F10** opens the focused Task's actions without\nchanging the open workspace.\n\nThe Task action menu moves work into a Wave or back to **No Wave** through the shared planning operation, retaining its workspace and drafts.\n\nEach Work keeps one pane layout and document store. Repository and Wave\nentry shows their retained conversation or an explicit **Open conversation** action.\nWaves pair that conversation with their objective, status, current Project and\nfull Task inventory, followed by their metrics. **Project history**, **Realign Projects\u2026** and **Workflow**\nopen the existing planning inspectors. The sidebar starts at 240 points wide;\ndrag its edge to resize or use the title-bar button or **\u2318\\** to toggle it.\nIts scroll position survives Wave and Task navigation. Working order survives\nrelaunch; ordinary launch still opens the repository, without acquiring a Session.\n\nClosing a repository window keeps its panes, selected Work and file drafts until\nDesktop quits. Reopening a known repository shows retained content immediately,\neven while repository resolution waits or fails. Errors remain visible; new Task\nlinks wait for resolution before delivery. Unknown repositories need an initial lookup.\n\nSelecting a retained Session reuses its surface. When a surface needs reconnecting,\nDesktop attaches to the recorded execution without starting a provider, replaying\ninput or taking control from another viewer. A failed connection stays visible.\n**Resume** does what `lf resume` does: it attaches to a running conversation, or\notherwise reopens its saved provider history. At launch Desktop runs\n`lf resume --all`, so conversations a reboot or crash interrupted come back\nunasked. Repository, Wave and Task conversation entry share metadata-only\npreparation; only a newly admitted conversation offers its first launch.\nFinite CLI requests time out after 30 seconds. Canceling preparation ends only\nthat request; running Sessions continue. If a change times out, refresh to learn\nits result before retrying.\n\nPane headers name the known provider, conversation and directory; arbitrary terminal\ntitles remain context under **Shell**, without guessing which program is running.\n\nTask rows show reported program status, Task IDs, stored PR links and the recorded\nremote Machine. Task IDs link to the issue when its URL is recorded; otherwise they\nremain plain text. Qualified Session excerpts show their source age; stale output\nfalls back to a labeled summary. Local Machine names stay hidden. Links open\nseparately from the Task row; unknown activity and live clients without reports\nshow no activity label.\n\nWork selection uses the theme\u2019s selection fill and contrasting text.\nFile selection keeps a neutral fill and edge; keyboard focus has a separate outline.\nOrdinary controls and links use text roles; the theme\u2019s accent emphasizes deliberate actions.\nStatus labels and shapes retain their meaning across palettes.\nChoose **Settings \u2192 Appearance** to preview the whole workspace. Set\n**Light theme** and **Dark theme** independently; **System** follows macOS using\nboth. System lists both pickers; Light or Dark lists only its own. Each picker\nshows built-ins, then **Yours**, ending with a dashed **Import file\u2026** tile.\n\n```yaml\n# ~/.lf/config.yaml\ntheme: \"light:Linen,dark:Hearth\"   # System\ntheme: \"Hearth\"                    # Dark (or Light) mode: one name\n```\n\n**Apply** rewrites only that line; **Cancel**, Escape or closing writes nothing.\nEdit it by hand and every window follows; a misspelled name keeps the last theme\nand names the fix. Absent means Loopflow Light/Dark. A repository's\n`.lf/config.yaml` never sets the theme.\n\nBuilt-ins are 12 light and 12 dark. **Loopflow Light** keeps the original\ncream/burgundy; **Loopflow Dark** is slate with warm bronze; **Linen** and **Hearth**\nare quieter light and charcoal alternatives.\n\nYour themes are Ghostty theme files in `~/.lf/themes/`; `~/.config/ghostty/themes/`\nis read too, never written. Names resolve to yours, then built-ins, then Ghostty's.\nA file named like a built-in overrides it. **Customize** on a built-in writes your\ncopy; on yours it edits in place. **Delete** removes yours (**Revert to built-in**\nfor an override). **Import file\u2026** copies a theme into Yours, accepting only the\npicker's appearance; a dark file in the Light picker explains itself instead.\n\n```\nbackground = #171924\nforeground = #cad2ef\npalette = 4=#7aa2f7\nloopflow-accent = #3d59a1    # optional app roles; the rest derive from ANSI colors\n```\n\nFiles read up to 256 KiB of UTF-8. Six-digit RGB background/foreground are\nrequired; cursor, selection, `palette = N=#RRGGBB` and `loopflow-` roles are\noptional. Preview explains defaults, repeats and omitted settings. Fonts,\ncommands, keybindings, includes and theme references are never followed.\n\nUnreadable app/default/selection/cursor text prevents Apply; ANSI colors keep\ntheir source values. Personal non-color Ghostty settings still load; its `theme =` is ignored and its file never written.\nSource and license notices ship offline with the catalogue.\n\n**Auto-Ship** hands a Task off; it leaves Working tasks and its ship process lands it.\nIt sits at the right end of the Workflow bar under the jump bar, beside the Task's\nstages as dots (click them for each stage) and what is running now. While shipping,\nthe same spot holds Stop Auto-Ship, and the toast's Undo is Stop Auto-Ship. Open a Dashboard with `state:shipping` to watch it.\n\n```text\n\u2318T          new shell tab in the Task\u2019s Shell tool\n\u2303`          show / hide Shell\n\u21e7\u2318E         show / hide Files\n\u2318\u2325\u2190/\u2192/\u2191/\u2193   focus the visual neighbor\n\u2318\u21e7Return    zoom the focused pane\n\u2318W / \u2318\u21e7T    close the selected tab / undo close\n\u2318F          find in the focused terminal\n```\n\nPanes sit in rounded islands with small gutters; drag a gutter to resize.\n**View \u2192 Zoom Focused Pane** and **View \u2192 Focus Pane** expose the same pane controls.\n\nThe focused pane has a quiet raised edge. Copying selected text or a command\nblock briefly confirms the number of copied lines without moving focus.\nFind reserves its own row above the terminal, so it never covers a match.\nReturn / Shift-Return select the next / previous match; Escape closes Find.\nSearch and terminal state stay with their retained pane when switching Work.\n\nTask workspaces start with the Session on the left and Files on the right,\nat 61.8/38.2. Use **View \u2192 Toggle Shell** or **Toggle Files**, or their shortcuts.\nIf every pane is hidden, **Show pane** restores the retained pane; **Open conversation**\nremains available when the Task has no conversation open.\nShell holds retained shell tabs; Files holds documents, **Brief**, **Changes** and\nrecorded **Pull request** tabs. Hidden tools keep their clients and drafts. Files starts with its chooser closed. Click the file-browser toggle or press\nCommand-P in the file pane to search **scratch** and files changed from the\nbranch's recorded parent commit. Selection closes the dropdown; pin it to keep\nthe list alongside the document (Control-Command-B). Escape dismisses the dropdown.\nSidebar selection switches the whole\nTask workspace; selections inside a Task can focus its companion.\nResizing or closing the browser is remembered while the window stays open;\nlayouts are not yet restored after quitting the app.\n\nChoose **PR** for a compact GitHub page: status, checks, pending reviewers,\ndescription and change totals. Expand **Files changed** and individual files to\nread published patches. Refresh updates GitHub data using the signed-in GitHub\nCLI on this Mac. Missing access and omitted large/binary patches are shown inline;\nlocal uncommitted edits stay in Files.\n\nOpen **\u2022\u2022\u2022** or press Command-/ for the selected Task\u2019s actions. Row context\nmenus use the same actions for the clicked Task. Command-T adds a shell tab. The main Session's menu switches between **Claude**,\n**Codex**, and **OpenCode**, continuing the same Session with its history.\n**Reset session** starts a fresh primary conversation/process from current Work\ninstructions, without replaying the previous conversation; its history remains\navailable. Reset preserves the previous terminal and client. Provider switching\nfirst reads its saved history, then replaces the current provider process. If the\nprovider has not saved a transcript yet, the current terminal stays open; finish\nits first turn and retry the switch. A failed status observer reconnects on the\nnext status event without replacing the conversation.\nRepository, Wave, Task and exact Session\npreparation all use `lf connect --prepare`; reset uses `--fresh` for its scope.\n\nShell panes with Ghostty shell integration group each completed command and its\noutput into a full-width block. A command that exited non-zero has a red\nbackground. Click anywhere in a block to select the whole unit; drag to select\ntext instead. There is one selection at a time, and Command-C or the context\nmenu copies it: a block copies its command and all of its output. Right-click\nkeeps the selection it lands on. A selected block clears when you type or press\nEscape. Command-Up and Command-Down jump between prompts. The live prompt remains ungrouped;\nSession/provider panes keep their native TUI behavior and do not expose shell\ncommand blocks.\nAutomatic integration depends on the configured shell; macOS `/bin/bash` is\nexcluded by the pinned Ghostty build. A zsh shell still on the macOS default\nprompt gets a small dim directory line above each bold command, with the gap\nbetween blocks shared evenly; any other prompt is left as it is.\n\nTerminals start from Desktop's own terminal settings. A launcher's `NO_COLOR`,\n`TERM`, pager and agent variables do not reach them, so provider CLIs keep their\ncolors however Desktop was opened.\n\nIf macOS cannot provide Ghostty's display link, terminals use timer rendering.\nThe app logs the CoreVideo error code; the user's Ghostty configuration is unchanged.\n\nA Task workspace holds three designated panes \u2014 session, shell and browser \u2014\narranged freely by dragging, zoom and hide; Wave and repository workspaces hold\nonly the session pane. The session pane shows one conversation and switches when\nanother opens. \u2318T adds a shell tab. The browser's tabs are the Task's Files, its\nGraph processes and http(s) pages. \u2318W closes the selected tab, or hides the pane.\n\u21e7\u2318T puts the last closed tab back where it was, its shell still running.\n\n**View \u2192 Toggle Files** shows a Task's checkout in the browser pane beside the\nretained terminal. Expand folders to read one page of up to 500 entries;\n**Load more** continues the directory and **Show ignored** includes ignored paths.\nTracked, unchanged and untracked files remain available without an active PR.\n**Changes** optionally compares the worktree with the Task PR's\nrecorded base; **HEAD** compares with its current commit. The displayed SHA pins\nthe file list and selected diff. A recorded PR links above the file navigator.\nUse \u2191/\u2193 in the navigator to select files; hover a row for its full path.\nClosing the pane keeps its drafts in this window.\n\n**Read** is where documents open: Markdown renders formatted, HTML as a live\npage that runs its scripts but never reaches the network. Links open in the\nbrowser. **Edit** retains editable UTF-8 drafts and selection in this window;\n**Diff** shows the draft comparison read-only.\n\nWhen an agent writes a `scratch/**/*.md` or `.html` file, Files reloads it if it\nis showing, or follows it. It takes the view only when nothing is selected, when\nthe current document was itself followed, or when you haven't touched Files for\ntwo minutes. Edit, Diff, an unsaved draft or keyboard focus in Files keep your\nview; the page then opens as a tab beside it.\n\nTask headers show the recorded checkout;\nterminal and files follow that Task without a separate worktree selector.\nChanging Work assignment leaves the recorded checkout Machine and path intact.\nThe browser retains its opening location through Close/Undo, including a first open\nwithout a Session link. New shell tabs use the Task's recorded location;\nexisting tabs and file drafts keep their original locations.\nUnknown or changed owners stay unavailable without redirecting retained drafts.\n\u2026 (813 more lines)", "scratch/loo-515-task-details.md": "# LOO-515 \u00b7 Task details beside the conversation\n\nStatus: **draft design** (kickoff, 2026-10-28). Experience choices below are the\nplan's proposals; Jack Heart's demo review accepts or redirects them. Accepted\ninputs: LOO-497 (one Files tool per Task, document/Brief/Changes tabs, hidden\ntools keep drafts), LOO-489 Console (one titlebar, Lato, neutral selection),\nLOO-327 (document per Task/path, drafts, recovery), the LOO-515 brief.\n\n## Problem\n\nJack finds the Files tool's Brief, Pull request and file views poor to use. In\nthe current code (`swift/LoopflowMac/Views/TaskFilesView.swift`,\n`TaskPullRequestView.swift`, `PullRequestStore.swift`):\n\n- **No identity or hierarchy.** A single 30 pt strip mixes `Brief`, `Changes`,\n  `Pull request` and every open file path as identical caption-sized plain\n  buttons in a horizontal scroller. Nothing marks the selected page, nothing\n  names the Task, and `Changes` is not a page \u2014 it flips Files into Diff mode\n  and pins the navigator.\n- **Brief** is identifier, title, due date and raw Markdown. No Task state,\n  PR state or next move; related Tasks are dead Linear links; long briefs have\n  no outline and lose scroll on every page switch.\n- **Pull request** only appears once a GitHub URL exists, ignores Loopflow's own\n  `PrSnapshot.phase` (working/publishing/open/merged/abandoned), reads GitHub once\n  on appear and shows \"Updated 3 hours ago\" in small caption under the same\n  green ticks as a fresh read. It renders a second, GitHub-sourced patch viewer\n  (`fileList`, `coloredPatch`, `loadFiles`) beside the local Diff.\n- **Files** cannot browse the checkout: the navigator lists only `scratch/` and\n  changed paths. `lf task files` (paged, ignore-aware, remote-routed) still\n  exists in Rust; its Swift wrapper was deleted in #1719 when nothing used it.\n  Location is never shown. Markdown, HTML and patch scroll positions reset when\n  you switch page, file or Task.\n\n## Demo\n\nIn a Task workspace with the conversation on the left and Files on the right:\n\n1. Press \u2325\u23181. **Brief** shows `LOO-515 \u00b7 Make Task PR\u2026` in the header, a state\n   line (`Moving \u00b7 kickoff running \u00b7 PR none`), an outline of the brief's\n   headings/Acceptance, and related Tasks `LOO-489 LOO-497 LOO-416 LOO-402` as\n   chips that open those Tasks in-app. Scroll halfway down.\n2. \u2325\u23182. **Changes** shows the PR card (`Open #1762 \u00b7 3 passed \u00b7 1 pending \u00b7\n   read 20 s ago`, `Review required`, `Open on GitHub \u2197`) above the Task's\n   changed files with +/\u2212 counts. Click `TaskFilesView.swift` \u2192 its Diff opens\n   in **Files** with the location breadcrumb `this Mac \u00b7 loopflow.loo-515\u2026/\n   swift/LoopflowMac/Views`.\n3. \u2325\u23183, expand `rust/loopflow/src/ops/task/` in the tree, open `directory.rs`.\n4. Click the conversation, ask \"why is PAGE_SIZE 500?\", read the answer.\n5. Switch to another Task with Cmd-2 and back with Cmd-1: Files, the tree's\n   expanded directories, the Diff's scroll and the Brief's scroll are where you\n   left them; the conversation never left the screen.\n6. Edge cases in the same build: a no-PR Task (`No pull request yet \u00b7 changes\n   below are local`), `gh` offline (`GitHub unavailable \u00b7 last read 14 min ago`,\n   checks greyed), a merged PR on an open Task (`Merged \u00b7 Task still open`), a\n   20k-word brief, `node_modules`-scale directory paging, a deleted file.\n\n## Chosen approach\n\n### One Files tool, three pages, one header\n\nKeep the existing layout: conversation pane left, the one Files browser pane\nright at 61.8/38.2 (`swift/README.md`). Nothing replaces the conversation; no\nnew panes. Inside Files:\n\n```\n\u250c LOO-515 \u00b7 Make Task PR, file-browser\u2026      [Brief|Changes|Files]  \u22ef \u2510  header\n\u2502 (Files page only) README.md  TaskFilesView.swift \u00d7   \u25e7 Read\u25be \u2913      \u2502  doc row\n\u2502 this Mac \u00b7 loopflow.loo-515\u2026/swift/LoopflowMac/Views                 \u2502  location\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n```\n\n- **Header** (one row): Task identifier (mono) + title (truncating) on the\n  left, a segmented control `Brief \u00b7 Changes \u00b7 Files` on the right. Shortcuts\n  \u2325\u23181/2/3 register as one pane-scoped `DesktopAction` (`files-page`, arg\n  `page`) beside `toggle-browser` in `DesktopActions.swift`, so they appear in\n  the View menu and show Files if hidden. No existing \u2325\u2318digit binding; Cmd-number\n  stays stable slots, \u2325\u2318arrows stay pane focus. The identifier comes from the pane's Task, so \"which\n  Task is this?\" is answered on every page.\n- **Document row** appears only on the Files page: open document tabs (file\n  name, full path in help, dirty dot, close), navigator toggle (\u2318P), Read/Edit/\n  Diff menu, Save. Today's mixed strip is deleted.\n- **Location line** on the Files page: Machine label + checkout leaf + current\n  directory of the selection. A remote Task names its Machine; an unavailable\n  location shows the existing error and never resolves locally (already enforced\n  by `SessionWorkspace.files(for:)`; keep it).\n- At widths < 360 pt the segmented control collapses to a menu; the title\n  truncates before the control does.\n\n`TaskFilesStore.Page` becomes `.brief | .changes | .files`. The pane program\nmenu's per-page buttons keep working through the same enum.\n\n### Brief\n\nDerived entirely from the `RoadmapTask` the pane already receives; no new read.\n\n- **Status block** (top, always visible without scrolling): Task state and\n  reason (`condition`, `nextMove.reason`), current Graph step\n  (`latestGraphProcess`/`execution`), PR chip from `pr.phase` (click \u2192 Changes),\n  due date. Evidence older than `condition.evidenceAgeSeconds` threshold reads\n  \"as of \u2026\".\n- **Related Tasks**: Task identifiers detected in the description with the\n  existing `ChatReference` detector, shown as chips; click opens\n  `loopflow://<repo>/task/<id>` (`WorkDestination`). Unknown identifiers still\n  render as text. This is how \"relevant dependencies\" become findable without a\n  new relations field.\n- **Outline**: when the brief has \u2265 2 headings or a bold `Acceptance:` lead,\n  a compact jump list above the body; clicking scrolls to that block.\n- **Body**: `MarkdownBlocks` at 680 pt reading width, selectable, links open\n  externally.\n- **Changed brief**: the store remembers the description hash last shown for\n  the Task; if it differs on return, a quiet `Brief updated` line appears with\n  the scroll kept at the same block index. Empty description: `No brief\n  recorded \u00b7 edit with lf task edit LOO-515` (copyable command).\n\n### Changes (PR + local changes)\n\nOne page answers \"what changed and where is it reviewed\".\n\n- **PR card**, two clearly separated facts:\n  1. *Loopflow's record* (`RoadmapTask.pr`): none \u00b7 working \u00b7 publishing \u00b7\n     open \u00b7 merged \u00b7 abandoned, plus merge request mode. This is authoritative\n     for \"is there a PR\".\n  2. *GitHub's reading* (`PullRequestStore`, `gh pr view`): status, checks\n     summary (expandable list), review decision, pending reviewers, collapsed\n     description, `Open on GitHub \u2197`, `Files changed on GitHub \u2197`.\n- **States** (each with distinct copy, not just colour):\n  - no PR \u2192 `No pull request yet \u00b7 changes below are local`.\n  - publication requested, no GitHub URL \u2192 `Publishing\u2026` with requested time.\n  - GitHub read failed \u2192 `GitHub unavailable: <reason>`; any retained reading\n    is shown dimmed under `Last read <relative>`; check icons go neutral.\n  - reading older than 2 min, or GitHub head \u2260 `changes.headCommit` \u2192 `Stale \u00b7\n    read <relative>` / `Local checkout is ahead of the PR` and dimmed checks.\n  - merged/abandoned \u2192 `Merged <sha>` / `Abandoned`, plus the Task's own state\n    (`Task still open`), never a completion claim.\n- **Freshness**: refresh on page appear, on `pr.publication` change, every 60 s\n  while the Changes page is visible, and by the refresh button. No polling when\n  hidden.\n- **Changed files** (local comparison, `lf task diff --files`, existing\n  `refreshChanges`): rows with status, path (middle-truncated), +/\u2212, dirty dot;\n  click opens the file's Diff on the Files page. `Parent \u00b7 <sha>` and `Open\n  saved versions \u2197` move here from the navigator foot.\n\n### Files\n\n- **Navigator** = filter field, pinned `scratch` group (agent pages, unchanged\n  follow behavior), then the checkout **tree** from `lf task files <issue>\n  <dir> --json` (restore `RegistryQuery.taskFiles` + `TaskDirectory` DTO).\n  Directories load lazily on expand, 500 entries per page with `Load more`.\n  Changed paths get a change badge from the existing `changes` snapshot.\n  Keyboard: \u2191/\u2193 move, \u2192/\u2190 expand/collapse, Return opens, \u2318P toggles, Esc\n  dismisses dropdown. Filter matches loaded names plus scratch/changed paths\n  (no recursive server search in this Task).\n- **Docked vs dropdown**: unchanged mechanism, docked threshold raised to\n  480 pt so the document keeps \u2265 300 pt.\n- **Retention (in-app)**: expanded directories, loaded pages, tree selection,\n  per-document reading scroll (Markdown/HTML), per-path Diff scroll, Brief and\n  Changes scroll all live on `TaskFilesStore`, which `SessionWorkspace`\n  already retains per Task across switches. Drafts/tabs/selection continue to\n  persist across restart through the existing `WorkBrowserTab.files` intent.\n- **Failed reads**: a directory read failure shows inline under that directory\n  with Retry; a missing file keeps the existing `File no longer exists`.\n\n## Risk findings\n\n- `lf task files` works today (`lf task files LOO-515 . --json` returns sorted\n  entries) and is in the remote-routable set (`lf.rs:2729`,\n  `lf/commands/ssh.rs:44`), so remote Tasks browse through their Machine. No\n  Rust change required.\n- Its DTO fixture was removed with the Swift wrapper; restoring the Swift DTO\n  re-adds `tests/fixtures/dto/task_files.json` (git: `db5736d11^`) and the\n  Rust/Swift fixture tests per the DTO rule.\n- `RoadmapTask` has no dependency relations; detection over description text\n  is the only source without a new Linear read. Accepted as the scope here.\n- Page and scroll are not in the persisted `WorkBrowserTab.files` intent;\n  adding them is a Rust/Swift DTO + migration change owned by LOO-497/416 \u2014\n  excluded (see Exclusions).\n- GitHub reads cost one `gh` process per refresh; 60 s cadence only while the\n  Changes page is visible keeps it bounded to one Task at a time.\n\n## Alternatives considered\n\n- *Separate Brief / PR panes beside Files*: violates LOO-497's one-Files-tool\n  decision and squeezes the conversation. Rejected.\n- *Keep PR as its own page*: the PR's useful content is state + review links;\n  the files list duplicated the local Diff with a weaker GitHub-patch renderer.\n  Merging into Changes removes a page and a diff renderer.\n- *Brief as a popover from the titlebar*: loses scroll and selection, hides\n  from keyboard. Rejected.\n- *Recursive tree from `git ls-files`*: fast but omits untracked files and does\n  not route remotely; `lf task files` already does both.\n\n## Current \u2192 target architecture\n\n| | Current | Target |\n|-|-|-|\n| Page model | `Page.task/.pullRequest/.files`; `Changes` = files+diff+pinned | `Page.brief/.changes/.files` |\n| Header | mixed strip of pages + doc tabs | identity + segmented pages; doc row only on Files |\n| PR source | GitHub only, gated on URL | `RoadmapTask.pr` phase + GitHub reading with freshness |\n| PR diff | GitHub patch list in PR view | local Diff only; GitHub link for external review |\n| Navigator | scratch + changed paths | scratch + lazy checkout tree (`lf task files`) |\n| Retention | documents/drafts | + tree, scroll per page/document |\n\nNo new store, writer or wire type except restoring the `TaskDirectory` DTO.\n\n## Delete \u2014 do not maintain\n\n- `PullRequestStore.loadFiles`, `files`, `filesError`, `loadingFiles`,\n  `showsFiles`, `expandedFiles`, `fileGeneration`; `GitHubPullRequestFile`.\n- `TaskPullRequestView.fileList`, `coloredPatch`, the `showsFiles` task.\n  The view itself folds into the Changes page as the PR card.\n- `PullRequestTests.publishedDiffDisclosesMissingAndPartialPatchesAndRenames`\n  (exclusive to the deleted GitHub patch list). Keep the checks test and the\n  publication-clears test (rename to the card's state).\n- The navigator's `Changed files` section and its footer (`Parent`, `Open\n  saved versions`) \u2014 moved to Changes.\n- The `Changes` button's files+diff+pinned behavior and the mixed page/tab\n  strip in `TaskFilesView`.\n\n## Forbidden outcomes\n\n- A second Diff renderer, or a second file list that disagrees with\n  `lf task diff --files`.\n- Showing a GitHub reading without its read time, or green checks on a failed\n  or stale reading.\n- Any local path fallback for a remote/unavailable checkout.\n- Treating `merged` or all-green as Task completion in copy or state.\n- New panes, or hiding the conversation to show details.\n\n## Exclusions\n\n- Persisting page/scroll/tree expansion across app restart (LOO-497/416 own the\n  persisted intent shape).\n- Waiting/attention indicators in navigation rows (LOO-402).\n- Recursive server-side file search, editing outside text files, an IDE.\n- Linear relation fields for dependencies; PR history beyond the current\n  `RoadmapTask.pr` (no multi-PR reader exists in the row).\n\n## Internal slices (one PR)\n\n1. **Delete** the GitHub patch list and its store state/tests; rename `Page`.\n2. Header + segmented pages + doc row; Brief page with status, related Tasks,\n   outline, changed-brief marker.\n3. Changes page: PR card states/freshness + moved changed-file list.\n4. **This slice to prove first:** Files tree via restored `taskFiles` wrapper\n   and DTO fixture, keyboard navigation, location line, scroll retention.\n5. README (`swift/README.md` Files section) updated to the three pages.\n\n## Done when\n\n- A Task workspace shows Task identity in Files on every page, with Brief,\n  Changes and Files reachable by click and \u2325\u23181/2/3, and the conversation pane\n  unchanged in size and focusable throughout.\n- Brief shows state, PR chip, related Tasks and an outline for structured\n  briefs; empty and changed briefs read correctly.\n- Changes distinguishes none / publishing / unavailable / stale / open /\n  merged / abandoned with distinct text, and opens any changed file's local\n  Diff.\n- Files browses the actual checkout tree (local or remote Machine), paginates\n  large directories, shows location, and survives page/Task switches with\n  tree, selection, scroll and drafts intact.\n\u2026 (21 more lines)", "scratch/questions.md": "# LOO-515 open questions and assumptions\n\n- Assumed (kickoff 2026-10-28): PR becomes part of a **Changes** page rather than its own page, and the GitHub patch list is deleted in favour of the local Diff plus `Open on GitHub \u2197`. Reversible in review; Jack Heart's demo decides.\n- Assumed: \u2325\u23181/2/3 for Brief/Changes/Files (no existing binding).\n- Assumed: \"relevant dependencies\" = Task identifiers detected in the brief text; no Linear relations read in this Task.\n- Assumed: page, scroll and tree expansion are retained in-app across Task switches, not across app restart (persisted intent belongs to LOO-497/416).\n", "README.md": "# Loopflow\n\n```bash\ncurl -fsSL https://loopflow.studio/install.sh | sh\nlf init\nnpx skills add loopflowstudio/loopflow --skill loopflow -g -y   # teach your coding agent to use lf\n```\n\n`lf` is how your agent orchestra conducts itself. It's a task system for coding\nagents: you say what you want, and each Task gets its own conversation, its own\nworkflow and its own pull request. Organize Tasks into Waves to give each area of\nwork its own defaults. It works with Claude Code, Codex, OpenCode and Pi, on your\nexisting subscriptions, inside whatever terminal, multiplexer and tracker you\nalready use.\n\n**1. A Task is a conversation with a workflow behind it.**\n\n```bash\nlf task create --title \"fix the flaky retry test\"   # prints the Task ID\nlf -b task run <ID>                                   # its worktree, its agents, its pull request\nlf resume --task <ID>                                 # its conversation, from any terminal\n```\n\nEach Task has:\n\n- **One conversation.** A persistent chat thread with your agent where everything\n  about the Task goes: you talk in it, reviews happen in it, results come back to\n  it. One context, on whichever harness and login it runs; it outlives terminals\n  and crashes.\n- **A workflow.** The Graph it runs (design, build, demo, land), each step in the\n  Task's own worktree and branch. `lf task run` stops at the steps where you take\n  part and the rest run without you; `lf -b task run` runs every step itself.\n- **Its own pull request, branch and tracker issue,** kept together.\n- **Its history.** Every conversation, Graph run and step, and what each cost.\n\n```bash\nlf comment <ID> \"keep the retry budget at 3\"   # reaches the next step, in its context\nlf task status <ID>                            # where it is in its workflow, and what it needs from you\nlf history usage --task <ID>                   # what it cost\nlf land --wait-and-fix                         # merge when checks pass; fix them if not\n```\n\nThe last install line teaches your own coding agent to do all of this, so you\ncan just ask it: *\"Split the auth cleanup into Tasks and run them with lf.\"*\n[What the skill teaches](https://github.com/loopflowstudio/loopflow/blob/main/skills/loopflow/README.md).\n\n**2. Write down how work runs.** A Task's workflow is a Graph: a YAML list of\nSkills, and a Skill is a Markdown file, both in your repository and reviewed like\ncode. Each step can name its own agent.\n\n```markdown\n<!-- .lf/skills/audit.md -->\nAudit auth changes on this branch. Fix missing validation and untested paths.\n```\n\n```yaml\n# .lf/graphs/ship-api.yaml\n- interactive: design   # you take part; leaves scratch/<task>.md\n- implement             # leaves commits on the branch\n- audit\n- gate                  # leaves passing checks\n```\n\n```bash\nlf audit                        # one Skill, here and now\nlf graph ship-api               # design with you here, then the rest on its own\nlf task run <ID> ship-api       # one Task through it; stops at design and waits for you\nlf -b task run <ID> ship-api    # every step headless, design included, to a merged PR\n```\n\nA step marked `interactive:` is where a person takes part. Each step can name its\nharness (`agent:`); `-i`, `-b`, `-a` and `--machine` choose for the whole run.\n\nLoopflow ships reasonable Graphs for software engineering, and they are\ntemplates. Copy one with `lf graph customize pursue`, change it, or write down\nthe way you work and share it.\n\n**3. Organize Tasks into Waves.** A Wave is an area of work with its own goal,\nmemory and plan, and its own setup for every Task in it: the Graph, the agent,\nthe machine and the login that pays. Your repository is the Wave for Tasks\nwithout one.\n\n```yaml\n# .lf/wave/infrastructure/config.yaml, committed: shaped like .lf/config.yaml\ngraph: auto           # infrastructure Tasks go from request to merged PR without you\nagent: claude:opus\n```\n\n```bash\nlf --wave infrastructure set machine mini                       # and run on your mini\nlf --wave infrastructure set account.claude work@example.com    # billed to your work login\nlf wave status infrastructure                                   # each setting and where it came from\n```\n\n**Without a Task,** `lf` still launches any agent or Skill directly:\n\n```bash\nlf : \"fix the flaky retry test\"            # an agent, on whichever of your logins has room\nlf -a codex : \"fix the flaky retry test\"   # the same thing on Codex\nlf debug -c                                # a Skill: paste an error, it finds and fixes the cause\nlf resume --all                            # after a crash or reboot, every interrupted conversation comes back\n```\n\n## What else it does\n\nYou want to do something; here's how through `lf`.\n\n| You want to\u2026 | |\n|---|---|\n| use every Claude and Codex login you pay for, routed to the one with room | `lf account` |\n| run on Claude Code, Codex, OpenCode or Pi, per run or per Skill | `lf -a codex : \"\u2026\"` |\n| run on your own machine over SSH | `lf --machine mini -b task run <ID>` |\n| rent a machine from Daytona, Modal, RunPod or AWS for one Task and give it back after | `lf task run <ID> --rent <template>` |\n| land when checks pass, with CI failures repaired for you | `lf land --wait-and-fix` |\n| see what agents cost, by Task, Wave or week | `lf history usage --weekly` |\n| open work in Desktop, cmux, Herdr, tmux or a terminal | `lf open --task <ID>` |\n| plan in Git with no tracker, or in Linear | `lf task list` |\n| keep a longer objective moving with its own memory, plan and setup | `lf wave status` |\n| cut a release | `lf release run <version>` |\n\n## Needs\n\n| You need | For |\n|---|---|\n| macOS or Linux, `git` | Everything |\n| [Claude Code](https://docs.anthropic.com/en/docs/claude-code), [Codex](https://github.com/openai/codex), [OpenCode](https://github.com/anomalyco/opencode) or [Pi](https://github.com/earendil-works/pi) 1.3+, signed in | Every run; each has its own cost |\n| [`gh`](https://cli.github.com), signed in | Pull requests (GitHub is the code host today) |\n| [Linear](https://linear.app) | Optional; the plan syncs through your Git remote by default |\n\n## What it touches\n\n- `~/.local/bin/lf` and `~/.lf/`: the binary, your config and a local SQLite store\n  of Tasks, conversations and runs.\n- Worktrees beside your repository, one per Task (`../<repo>.<task>`).\n- `scratch/` in your repository for working notes; `.lf/` once you add your own\n  Skills, Graphs or Waves.\n- Your provider logins. There is no hosted service: conversations stay on your\n  machine, and only the plan travels, as a Git ref or through Linear.\n\nRemove it with `rm ~/.local/bin/lf && rm -rf ~/.lf`, then delete any worktrees it\ncreated with `git worktree remove`.\n\n## Docs\n\nEach page picks up where the last one stops:\n[Get started](docs/getting-started.md) \u2192 [Work](docs/work.md) \u2192\n[Sessions](docs/sessions.md) \u2192 [Ops](docs/ops.md) \u2192 [Surfaces](docs/surfaces.md) \u2192\n[Telemetry](docs/telemetry.md) \u2192 [Orchestration](docs/orchestration.md).\nWhen something breaks: [Troubleshooting](docs/troubleshooting.md). Everything else:\n[For agents](docs/agent-api.md) \u00b7 [`lf` reference](docs/lf-reference.md).\n\nAgents can read [llms.txt](https://loopflow.studio/llms.txt) or any page as\nMarkdown at its `.md` URL.\n\n## Developing Loopflow\n\n`AGENTS.md` is the style guide, `scripts/README.md` covers the test runner,\nand `RELEASE_NOTES.md` carries the release history.\n\n```bash\nuv run python scripts/install.py local       # build under local-bin/\nLF_HOME=\"$(mktemp -d)\" local-bin/lf wave list --json\n```\n\n## License\n\n[MIT](LICENSE)\n", "swift/LoopflowMac/DesktopActions.swift": "// The one mutation path for Desktop gestures. The shortcut monitor, menus,\n// Keyboard Shortcuts window and the Desktop socket's `perform` all\n// look actions up here and call `perform`; `lf desktop` verbs name them.\n\n#if os(macOS)\nimport AppKit\nimport Loopflow\nimport SwiftUI\nimport WebKit\n\n/// A default key and the arguments pressing it supplies (\u23182 is `goto index=2`).\nstruct DesktopKeyBinding: Equatable {\n    enum Key: Equatable { case character(Character), `return`, tab, left, right, up, down }\n    let key: Key\n    let modifiers: NSEvent.ModifierFlags\n    let args: [String: String]\n\n    init(_ key: Key, _ modifiers: NSEvent.ModifierFlags, args: [String: String] = [:]) {\n        self.key = key; self.modifiers = modifiers; self.args = args\n    }\n\n    var display: String {\n        let symbols: [(NSEvent.ModifierFlags, String)] = [(.control, \"\u2303\"), (.option, \"\u2325\"), (.shift, \"\u21e7\"), (.command, \"\u2318\")]\n        let prefix = symbols.filter { modifiers.contains($0.0) }.map(\\.1).joined()\n        return switch key {\n        case .character(let character): prefix + String(character).uppercased()\n        case .return: prefix + \"\u21a9\"\n        case .tab: prefix + \"\u21e5\"\n        case .left: prefix + \"\u2190\"\n        case .right: prefix + \"\u2192\"\n        case .up: prefix + \"\u2191\"\n        case .down: prefix + \"\u2193\"\n        }\n    }\n\n    var keyEquivalent: KeyEquivalent {\n        switch key {\n        case .character(let character): KeyEquivalent(character)\n        case .return: .return\n        case .tab: .tab\n        case .left: .leftArrow\n        case .right: .rightArrow\n        case .up: .upArrow\n        case .down: .downArrow\n        }\n    }\n\n    var eventModifiers: EventModifiers {\n        var result: EventModifiers = []\n        if modifiers.contains(.command) { result.insert(.command) }\n        if modifiers.contains(.shift) { result.insert(.shift) }\n        if modifiers.contains(.option) { result.insert(.option) }\n        if modifiers.contains(.control) { result.insert(.control) }\n        return result\n    }\n\n    func matches(characters: String?, keyCode: UInt16, specialKey: NSEvent.SpecialKey?, modifiers flags: NSEvent.ModifierFlags) -> Bool {\n        guard flags.intersection([.command, .shift, .option, .control]) == modifiers else { return false }\n        return switch key {\n        case .character(let character): characters?.lowercased() == String(character)\n        case .return: keyCode == 36 || keyCode == 76\n        // \u2303\u21e7\u21e5 arrives as backtab.\n        case .tab: characters == \"\\t\" || characters == \"\\u{19}\"\n        case .left: specialKey == .leftArrow\n        case .right: specialKey == .rightArrow\n        case .up: specialKey == .upArrow\n        case .down: specialKey == .downArrow\n        }\n    }\n}\n\n/// The window an action runs in and, for pane actions, the addressed pane:\n/// the focused one for keys and menus, an exact target for scripts.\n@MainActor\nstruct DesktopActionContext {\n    let model: WorkModel\n    let workspaces: SessionsWorkspaceRegistry\n    let workspace: SessionsWorkspace?\n    let pane: PaneState?\n    /// The addressed shell or browser tab; nil addresses the pane's selected tab.\n    let tab: String?\n    let args: [String: String]\n\n    init(model: WorkModel, workspaces: SessionsWorkspaceRegistry, workspace: SessionsWorkspace?,\n         pane: PaneState?, tab: String? = nil, args: [String: String] = [:]) {\n        self.model = model; self.workspaces = workspaces; self.workspace = workspace\n        self.pane = pane; self.tab = tab; self.args = args\n    }\n\n    func with(args: [String: String]) -> Self {\n        Self(model: model, workspaces: workspaces, workspace: workspace, pane: pane, tab: tab, args: args)\n    }\n\n    fileprivate func string(_ name: String) throws -> String {\n        guard let value = args[name] else { throw DesktopArgumentError(\"Missing argument \\(name)=\u2026; nothing changed.\") }\n        return value\n    }\n\n    fileprivate func integer(_ name: String) throws -> Int {\n        let value = try string(name)\n        guard let number = Int(value) else { throw DesktopArgumentError(\"\\(name)=\\(value) is not an integer; nothing changed.\") }\n        return number\n    }\n\n    fileprivate func boolean(_ name: String) throws -> Bool? {\n        guard let value = args[name] else { return nil }\n        switch value.lowercased() {\n        case \"true\", \"on\", \"yes\", \"1\": return true\n        case \"false\", \"off\", \"no\", \"0\": return false\n        default: throw DesktopArgumentError(\"\\(name)=\\(value) is not true or false; nothing changed.\")\n        }\n    }\n\n    fileprivate var addressed: (SessionsWorkspace, PaneState) {\n        get throws {\n            guard let workspace, let pane else { throw DesktopTargetError(\"Address a pane for this action; nothing changed.\") }\n            return (workspace, pane)\n        }\n    }\n\n    fileprivate var task: SessionsWorkspace {\n        get throws {\n            let (workspace, _) = try addressed\n            guard workspace.key.kind == .task else {\n                throw DesktopTargetError(\"Shell and browser belong to Task workspaces; nothing changed.\")\n            }\n            return workspace\n        }\n    }\n\n    /// The addressed pane's terminal: a shell's addressed or selected tab, or the session.\n    fileprivate var terminal: TerminalIdentity {\n        get throws {\n            let (workspace, pane) = try addressed\n            if let tab, let shell = workspace.multiplexer.shell(tab), let terminal = shell.terminal { return terminal }\n            guard let terminal = pane.terminal else {\n                throw RegistryQueryError(\"The addressed pane is not a terminal; no input was sent.\")\n            }\n            return terminal\n        }\n    }\n\n    /// Scripts fence input with the surface they inspected; menus use the current one.\n    fileprivate func surface(for terminal: TerminalIdentity) throws -> String {\n        if let surface = args[\"surface\"] { return surface }\n        guard let surface = workspaces.surfaces.surfaceIncarnation(for: terminal) else {\n            throw RegistryQueryError(\"The retained pane has no native surface; no input was sent.\")\n        }\n        return surface\n    }\n\n    /// Another pane of the addressed workspace, by pane ID or designated kind.\n    fileprivate func peer(_ name: String) throws -> PaneState {\n        let (workspace, pane) = try addressed\n        let selector = try string(name)\n        let store = workspace.multiplexer\n        let other = store.layout.pane(for: selector)\n            ?? PaneContent.Kind(rawValue: selector).flatMap { store.layout.pane(of: $0) }\n        guard let other, other.id != pane.id else {\n            throw DesktopTargetError(\"Choose another pane of the same workspace for \\(name)=\\(selector); nothing changed.\")\n        }\n        return other\n    }\n}\n\n/// The pane and tab an action affected, when it addressed or created one.\nstruct DesktopActionOutcome: Equatable {\n    var pane: String?\n    var tab: String?\n}\n\n@MainActor\nstruct DesktopAction {\n    let name: String\n    let title: String\n    let scope: DesktopActionScope\n    let arguments: [DesktopActionArgument]\n    let keys: [DesktopKeyBinding]\n    /// Keys and menus offer the action only where it can run.\n    let available: (DesktopActionContext) -> Bool\n    let run: (DesktopActionContext) throws -> DesktopActionOutcome?\n\n    init(_ name: String, _ title: String, scope: DesktopActionScope = .window, arguments: [DesktopActionArgument] = [],\n         keys: [DesktopKeyBinding] = [], available: ((DesktopActionContext) -> Bool)? = nil,\n         run: @escaping (DesktopActionContext) throws -> DesktopActionOutcome?) {\n        self.name = name; self.title = title; self.scope = scope; self.arguments = arguments; self.keys = keys\n        self.available = available ?? { context in scope == .window || context.pane != nil }\n        self.run = run\n    }\n\n    var descriptor: DesktopActionDescriptor {\n        DesktopActionDescriptor(name: name, title: title, scope: scope, arguments: arguments, keys: keys.map(\\.display))\n    }\n\n    /// Validate arguments, then run. A failure changes nothing.\n    @discardableResult\n    func perform(_ context: DesktopActionContext) throws -> DesktopActionOutcome {\n        if let unknown = context.args.keys.sorted().first(where: { name in !arguments.contains { $0.name == name } }) {\n            throw DesktopArgumentError(\"\\(self.name) takes no argument \\(unknown); see lf desktop actions. Nothing changed.\")\n        }\n        if let missing = arguments.first(where: { $0.required && context.args[$0.name] == nil }) {\n            throw DesktopArgumentError(\"\\(name) requires \\(missing.name)=\u2026; nothing changed.\")\n        }\n        // A view part named by `part` stands in for the pane.\n        if scope == .pane, context.args[\"part\"] == nil { _ = try context.addressed }\n        let outcome = try run(context)\n        return outcome ?? DesktopActionOutcome(pane: context.pane?.id, tab: context.tab ?? context.pane?.content.selectedTabID)\n    }\n\n    static func named(_ name: String) throws -> DesktopAction {\n        guard let action = all.first(where: { $0.name == name }) else {\n            throw DesktopArgumentError(\"Unknown action \\(name); see lf desktop actions. Nothing changed.\")\n        }\n        return action\n    }\n\n    /// The registry action and arguments a key press performs.\n    static func binding(characters: String?, keyCode: UInt16 = 0, specialKey: NSEvent.SpecialKey? = nil,\n                        modifiers: NSEvent.ModifierFlags) -> (DesktopAction, [String: String])? {\n        for action in all {\n            if let binding = action.keys.first(where: {\n                $0.matches(characters: characters, keyCode: keyCode, specialKey: specialKey, modifiers: modifiers)\n            }) { return (action, binding.args) }\n        }\n        return nil\n    }\n\n    /// The socket's entry: resolve the exact target, then perform.\n    static func perform(_ request: DesktopActionRequest, model: WorkModel,\n                        workspaces: SessionsWorkspaceRegistry) throws -> DesktopActionOutcome {\n        let action = try named(request.action)\n        var workspace: SessionsWorkspace?\n        var pane: PaneState?\n        if let target = request.pane {\n            (workspace, pane, _) = try workspaces.retainedPane(for: target)\n        }\n        return try action.perform(DesktopActionContext(model: model, workspaces: workspaces, workspace: workspace,\n            pane: pane, tab: request.pane?.tab, args: request.args))\n    }\n\n    // MARK: - Registry\n\n    private static let taskTool: (DesktopActionContext) -> Bool = { $0.pane != nil && $0.workspace?.key.kind == .task }\n\n    static let all: [DesktopAction] = navigation + panes + tools\n\n    private static let navigation: [DesktopAction] = [\n        DesktopAction(\"back\", \"Back\", keys: [.init(.character(\"[\"), .command)]) { context in\n            guard !context.model.navigation.backStack.isEmpty else { throw DesktopTargetError(\"Nothing to go back to. Nothing changed.\") }\n            context.model.goBack()\n            return nil\n        },\n        DesktopAction(\"forward\", \"Forward\", keys: [.init(.character(\"]\"), .command)]) { context in\n            guard !context.model.navigation.forwardStack.isEmpty else { throw DesktopTargetError(\"Nothing to go forward to. Nothing changed.\") }\n            context.model.goForward()\n            return nil\n        },\n        DesktopAction(\"goto\", \"Working Task\", arguments: [.init(name: \"index\", kind: .integer, required: true)],\n            keys: (1...9).map { .init(.character(Character(String($0))), .command, args: [\"index\": String($0)]) }) { context in\n            let index = try context.integer(\"index\")\n\u2026 (402 more lines)"};
window.BRIEF_515="Jack Heart finds the Task sidebar's PR, file-browser and Task-brief views poor to use. Make those views useful companions to the Task conversation: someone should quickly understand the requested outcome, inspect what changed and navigate the relevant files without losing their conversation or wondering which Task they are viewing.\n\nAcceptance:\n\n* Review the current rendered PR, file-browser and brief views together and design their hierarchy, sizing, navigation and interactions as one Task-details experience. Preserve an accessible conversation while inspecting details; choose concrete layout during design rather than assuming three new panels.\n* The brief is readable, with the Task's outcome, acceptance, relevant dependencies and current status easy to find. Long Markdown, links, empty/missing content and changed briefs remain usable. Do not force readers to reconstruct the current scope from a progress log.\n* The PR view identifies the Task's relevant PR and delivery/check state, makes changes and external review reachable, and distinguishes no PR, unavailable evidence, open, merged and historical PRs. Stale information must not look current; a green check or merged PR does not silently complete a Task.\n* The file browser starts from the Task's actual checkout/Machine, supports efficient directory/file navigation and readable file inspection, and makes location clear. Preserve selection, scroll position and any supported unsaved edits while moving among views and Tasks. Remote or unavailable paths must not silently resolve to local files.\n* Demonstrate a real review loop: read the brief, inspect a PR/change, locate a relevant file, ask or answer in the same Task conversation, switch away and return with context intact. Include long briefs, large/deep file trees, no-PR Tasks and failed reads; verify keyboard access and meaningful empty/loading states.\n\nProduct owns this cohesive sidebar/details improvement. Build on [LOO-489 \u00b7 Multitask navigation](<https://linear.app/loopflow/issue/LOO-489/enable-the-multitask-navigation-experience>), [LOO-497 \u00b7 Shared selection/arrangement APIs](<https://linear.app/loopflow/issue/LOO-497/drive-desktop-through-separate-selection-and-arrangement-apis>), and [LOO-416 \u00b7 Session continuity](<https://linear.app/loopflow/issue/LOO-416/keep-task-sessions-seamless-across-switching-and-app-restart>); preserve their active work and ownership. [LOO-402 \u00b7 Waiting indicators](<https://linear.app/loopflow/issue/LOO-402/show-which-task-is-waiting-from-the-sidebar-and-jump-to-it>) owns attention in navigation rows, not the contents of these detail views. Use existing Task/PR/file readers and edit/recovery APIs rather than adding another data store or an unrelated full IDE.\n\nJack requested a clear Product Task on October 18, 2026. Start with an experience design and hands-on review when selected; filing does not launch work.";
